      "rules" : [ {
        "data" : "Email",
        "condition" : "=",
        "field" : "BeginPhonecall:TalkTrackButtons:selectedButtonName"
      } ]
    }
  },
  "text" : "<div style=\"border-radius: 10px; padding: 10px; height: 250px; overflow-x: hidden; overflow-y: auto; background-color: #e8e8e8; font-size: 15px;\">\n<p><strong>If email contact preferred (or required) &ndash; send first introduction template email, </strong><strong>then (if required) send second introduction email:<br /></strong><br />&bull; EMAIL: <a href=\"https://portal.knowhow.service.anz/C/File/mor8ugyWEe2RDgBQVpUToA\" target=\"_blank\" rel=\"noopener\">1st Introduction email</a><br />&bull; EMAIL: <a href=\"https://portal.knowhow.service.anz/C/File/0t5y4vF5Ee6RKgBQVpUToA\" target=\"_blank\" rel=\"noopener\">2nd Introduction email</a><br />Upload email to CMOS files tab.</p>\n</div>",
  "label" : "TextBlock2",
  "controlWidth" : 12
}

