{
  "lwcComponentOverride" : "",
  "controlWidth" : 12,
  "label" : "TextBlock1",
  "text" : "<div style=\"font-size: 15px; border-radius: 10px; padding: 10px; height: 200px; overflow-x: hidden; overflow-y: auto; background-color: #e8e8e8;\"><strong>☐ Action financial remedy (if applicable)</strong><br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&bull; Provisionally close case in CMOS<br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&bull; Load payment request into <a href=\"https://webvoucher.apps.anz/Pages/MainPage.aspx\" target=\"_blank\" rel=\"noopener\">Webvoucher</a><br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&bull; Write case comment to show how you processed the Webvoucher.<br /><br /><strong>☐ Attach all relevant documents to CMOS (if applicable)<br /></strong><br /><strong>☐ Write case comment to show the case is now closed:&nbsp;</strong><br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&bull; Describe all actions you took, such as feedback to staff<br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&bull; Include information from other business units (if applicable)<br /><br /><strong>☐ Complete fields in CMOS &amp; close case:</strong><br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&bull; Ensure required letters have been sent (eg. for cases not closed within 5 days) and filed (go to Send Written Response if needed)<br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&bull; Ensure required fields in CMOS are completed as per &ldquo;<a href=\"https://portal.knowhow.service.anz/C/Xz3c9XvfEeakaQBQVpxDEQ?fromMenu=lNfUvYn5EeakaQBQVpxDEQ\" target=\"_blank\" rel=\"noopener\">Closing an IDR Complaint</a>&rdquo; process, including REAL, PSI, and Vulnerability checks as applicable.<br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&bull; Mark complaint status as &lsquo;Closed&rsquo;</div>",
  "show" : {
